const guideBody = `> A place to collect what matters, connect what you learn, and give your thinking room to grow.

## Your mind, with a little more room
Think of a **space** as a wing of your castle. Each one holds **channels** for narrower topics, and each channel can hold as many documents as you need.

Start with the four research spaces in the left rail, or create a space of your own. Nothing here is a fixed taxonomy.

## A simple research rhythm
1. **Capture** a question, a source, or a passing thought in the Inbox.
2. **Organize** it into a topic and a channel when its place becomes clear.
3. **Connect** it to another document using double brackets, like [[The research toolkit]].
4. **Develop** the idea. Move it from Seed to Draft to Growing as your understanding changes.

## Built for more than plain text
Use headings, **bold**, *italics*, lists, checklists, quotes, links, code, tables, and simple diagrams. Open [[The research toolkit]] for copyable examples.

| View | Use it for |
| --- | --- |
| Documents | Reading and organizing your research |
| Research board | Seeing ideas by their stage of development |
| Knowledge graph | Following connections between documents |

## A few useful habits
- [ ] Capture your first question with New document
- [ ] Give it a descriptive title and a couple of tags
- [ ] Link it to an existing document with [[The research toolkit]]
- [ ] Pin a document you return to often
- [ ] Export a backup from Workspace settings

## Your data belongs to you
Documents are saved **in this browser on this device**. They are not synced to an account or to GitHub. Clearing browser data can remove them. Export your workspace regularly; import that file on another device to bring your notes with you.

The starter documents are editable templates, not completed research or verified findings.`;
const toolkitBody = `## A small toolkit for complex ideas
This page demonstrates the formats available in your workspace. Edit it to see how each one is written. All content below is illustrative.

## Start with a question
> What would change my mind about this topic?

Separate **observation**, **interpretation**, and **uncertainty**. A good note can leave a question open.

### An evidence table
| Claim | Source to collect | Confidence | Next step |
| --- | --- | --- | --- |
| Working hypothesis | Primary document | Unassessed | Find evidence |
| Alternative explanation | Independent analysis | Unassessed | Compare assumptions |
| Open question | First-hand account | Unassessed | Record limitations |

### A research process diagram

\`\`\`diagram
Question -> Sources -> Evidence -> Synthesis -> New questions
\`\`\`

### A simple bar chart
Illustrative counts only — replace these with your own data.

\`\`\`chart
Primary sources | 8
Analysis | 5
Open questions | 3
\`\`\`

### Checklists and code
- [x] Define a clear research question
- [ ] Record source URLs and access dates
- [ ] Look for evidence against the hypothesis
- [ ] Distinguish missing evidence from negative evidence

\`\`\`text
Claim → Evidence → Interpretation → Uncertainty
\`\`\`

### Connected thinking
Use double brackets around an exact document title to make a link. Connections appear in the graph and as backlinks on the destination document.

Begin with [[Welcome to your mind castle]], [[Mapping the job market]], or [[Questions worth sitting with]].

---
External links use standard Markdown: [Wikipedia](https://en.wikipedia.org/). Links are references you choose; the workspace does not verify their contents.`;
const docSeed = (docId,title,space,channel,type,body,tags,pinned=false,status='seed') => ({id:docId,title,space,channel,type,body,tags,pinned,status,created:startTime,updated:startTime,starter:true});
function initialState(){return {version:1,spaces:structuredClone(seedSpaces),documents:[
  docSeed('welcome','Welcome to your mind castle','inbox','inbox','document',guideBody,['getting-started','workspace'],true,'growing'),
  docSeed('market-map','Mapping the job market','jobs','overview','document',`## The question\nWhat kind of work do I want to understand, and why?\n\nThis is a research starting point. Add a geography, timeframe, and definition of the market before collecting data.\n\n## Research map\n- **Demand:** Which roles are organizations seeking?\n- **Compensation:** What do comparable roles actually pay?\n- **Skills:** What is required, preferred, or trainable?\n- **Access:** Where do location, language, and credentials matter?\n\n## Evidence to collect\n| Signal | Source | Date | Limitation |\n| --- | --- | --- | --- |\n| Vacancy counts | To collect | — | Reposts and duplicates |\n| Advertised salary | To collect | — | Missing ranges and gross/net differences |\n| Hiring outcomes | To collect | — | Selection and reporting bias |\n\n## Next steps\n- [ ] Define the region and observation period\n- [ ] Save primary sources\n- [ ] Separate measured trends from impressions\n\nUse [[The research toolkit]] to structure the evidence.`,['careers','research-plan'],true,'draft'),
  docSeed('institutions','How institutions shape decisions','politics','institutions','document',`## Working question\nHow do rules, incentives, and institutional structures influence political decisions?\n\n> This is an outline for investigation, not a claim about a particular country or political group.\n\n## Keep three layers separate\n1. **Formal rules:** What do laws and procedures say?\n2. **Observed practice:** What happens in documented cases?\n3. **Interpretation:** What explanations fit the evidence?\n\n## Compare fairly\n| Dimension | Case A | Case B |\n| --- | --- | --- |\n| Decision-making authority | To investigate | To investigate |\n| Accountability mechanism | To investigate | To investigate |\n| Evidence and uncertainty | To investigate | To investigate |\n\n## An adjacent question\nWhat makes authority legitimate? Connect this to [[Questions worth sitting with]] and [[Belief, meaning & tradition]].`,['institutions','power'],false,'seed'),
  docSeed('questions','Questions worth sitting with','philosophy','questions','document',`## Leave room for a better question\nA collection of questions to revisit, rather than conclusions to defend.\n\n### Knowledge\n- What counts as good evidence?\n- When is it reasonable to withhold judgment?\n- How do I distinguish confidence from familiarity?\n\n### Ethics\n- What do I owe to people I will never meet?\n- How should intention and consequence be weighed?\n\n### Meaning\n- What makes a life meaningful?\n- How much of identity is chosen, inherited, or relational?\n\n> For each question, record competing answers in their strongest forms before choosing a position.\n\n## Connections\nExplore how these questions appear in [[Belief, meaning & tradition]] and [[How institutions shape decisions]].`,['epistemology','ethics','open-questions'],true,'growing'),
  docSeed('belief','Belief, meaning & tradition','religion','overview','document',`## A respectful comparative framework\nExplore religious traditions on their own terms. Distinguish a tradition's internal diversity from broad generalizations about it.\n\n## Lines of inquiry\n- **Texts:** Which sources are considered authoritative, and by whom?\n- **Practice:** How are beliefs expressed in everyday life?\n- **History:** How have institutions and interpretations changed?\n- **Meaning:** How are suffering, purpose, and belonging understood?\n\n## Source discipline\n1. Include primary texts and practitioners' perspectives.\n2. Record translation, edition, and historical context.\n3. Distinguish theological, historical, and sociological claims.\n4. State where interpretations disagree.\n\n## Open questions\n- [ ] Select a specific tradition and research question\n- [ ] Collect representative sources\n- [ ] Note internal disagreements\n\nRelated: [[Questions worth sitting with]].`,['comparative-study','meaning'],false,'seed'),
  docSeed('toolkit','The research toolkit','inbox','inbox','table',toolkitBody,['formatting','methods'],true,'growing')
],activity:[{text:'Your workspace is ready',detail:'Four spaces. A place to begin.',time:startTime},{text:'A few starting points, planted',detail:'Explore and make them your own.',time:startTime}]};}

function validateState(value){
  if(!value || value.version!==1 || !Array.isArray(value.spaces) || !Array.isArray(value.documents))throw Error('This is not a supported Mind workspace backup.');
  if(value.spaces.length>100 || value.documents.length>10000)throw Error('This backup exceeds workspace limits.');
  const unique=new Set();
  const spaces=value.spaces.map(s=>{
    if(!s || typeof s.id!=='string' || s.id==='inbox' || unique.has(s.id) || !/^[a-zA-Z0-9-]{1,100}$/.test(s.id) || typeof s.name!=='string' || !s.name.trim() || s.name.length>100 || !Array.isArray(s.channels) || s.channels.length>200 || !s.channels.length || s.channels.some(c=>typeof c!=='string'||!c.trim()||c.length>100) || new Set(s.channels).size!==s.channels.length)throw Error('A space in this backup is invalid.');
    unique.add(s.id);return {id:s.id,name:s.name,description:String(s.description||'').slice(0,300),icon:Object.hasOwn(ICONS,s.icon)?s.icon:'book',color:/^#[0-9a-fA-F]{6}$/.test(s.color)?({'#96bdad':'#57f287','#90afd3':'#5865f2','#b8a0d3':'#eb459e','#d3b17c':'#fee75c','#ce95a8':'#ed4245'}[s.color]||s.color):'#eb459e',channels:s.channels};
  });
  const docIds=new Set();
  const documents=value.documents.map(d=>{
    if(!d || typeof d.id!=='string'||docIds.has(d.id)||!/^[a-zA-Z0-9-]{1,100}$/.test(d.id)||typeof d.title!=='string'||!d.title.trim()||d.title.length>200||typeof d.body!=='string'||d.body.length>1000000||!['seed','draft','growing'].includes(d.status)||!['document','table','diagram'].includes(d.type)||!Array.isArray(d.tags)||d.tags.length>30||d.tags.some(t=>typeof t!=='string'||t.length>60)||!Number.isFinite(Date.parse(d.updated))||!Number.isFinite(Date.parse(d.created)))throw Error('A document in this backup is invalid.');
    if(d.space!=='inbox'&&!spaces.some(s=>s.id===d.space&&s.channels.includes(d.channel)))throw Error('A document refers to a missing space or channel.');
    docIds.add(d.id);return {id:d.id,title:d.title,body:d.body,space:d.space,channel:d.space==='inbox'?'inbox':d.channel,type:d.type,tags:d.tags,status:d.status,pinned:!!d.pinned,starter:!!d.starter,created:d.created,updated:d.updated};
  });
  const activity=Array.isArray(value.activity)?value.activity.filter(a=>a&&typeof a.text==='string'&&typeof a.detail==='string'&&Number.isFinite(Date.parse(a.time))).slice(0,20):[];
  return {version:1,spaces,documents,activity};
}
let loadError='',storedSnapshot=null;
let state;
try{const saved=localStorage.getItem(STORAGE_KEY);storedSnapshot=saved;state=saved?validateState(JSON.parse(saved)):initialState();}catch(e){state=initialState();loadError='Saved data could not be loaded. Export it from settings before resetting this browser.';}
let route={view:'home',space:null,channel:null,doc:null};
let tab='recent',layout='list',sort='updated',filter='',inspectorOpen=window.innerWidth>1250,navOpen=false,collapsed=false;
let toastTimer,modalReturnFocus=null,editorDirty=false;
const app=document.getElementById('app'),overlay=document.getElementById('overlay');
function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function saveState(next){try{if(loadError)throw Error('Existing data needs recovery first');if(localStorage.getItem(STORAGE_KEY)!==storedSnapshot){notify('Another tab changed this workspace. Copy your unsaved text, then reload before saving.');return false;}const serialized=JSON.stringify(next);localStorage.setItem(STORAGE_KEY,serialized);storedSnapshot=serialized;state=next;return true;}catch(e){notify(loadError||'Could not save. Browser storage may be full or unavailable. Export a backup and try again.');return false;}}
function mutate(fn,message){const next=structuredClone(state);fn(next);if(!saveState(next))return false;if(route.view==='doc'&&!docById(route.doc))route={view:'home'};if(message)notify(message);render();return true;}
function activity(next,text,detail=''){next.activity.unshift({text,detail,time:now()});next.activity=next.activity.slice(0,20);}
function spaceById(sid){return state.spaces.find(s=>s.id===sid);}
function docById(did){return state.documents.find(d=>d.id===did);}
function spaceName(sid){return sid==='inbox'?'Inbox':spaceById(sid)?.name||'Workspace';}
function spaceColor(sid){return spaceById(sid)?.color||'#949cf7';}
function dateLabel(d){return new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function documentIcon(d){return d.type==='table'?'table':d.type==='diagram'?'graph':'file';}
function statusLabel(s){return ({seed:'Seed',draft:'Draft',growing:'Growing'})[s]||s;}
function preview(d){return d.body.replace(/\[\[([^\]]+)\]\]/g,'$1').replace(/[#>*`|\[\]]/g,'').replace(/\s+/g,' ').trim().slice(0,115);}
function linksFrom(doc){return [...new Set([...doc.body.matchAll(/\[\[([^\]\n]+)\]\]/g)].map(m=>m[1].trim()))].map(title=>state.documents.find(d=>d.title.toLowerCase()===title.toLowerCase())).filter(Boolean);}
function graphEdges(docs=state.documents){const ids=new Set(docs.map(d=>d.id)),seen=new Set(),edges=[];for(const doc of docs)for(const linked of linksFrom(doc)){const key=[doc.id,linked.id].sort().join(':');if(linked.id!==doc.id&&ids.has(linked.id)&&!seen.has(key)){seen.add(key);edges.push([doc.id,linked.id]);}}return edges;}
function navigate(view,opts={}){const params=new URLSearchParams({view,...opts});if(location.hash.slice(1)===params.toString())readRoute();else location.hash=params.toString();}
function readRoute(){const p=new URLSearchParams(location.hash.slice(1));route={view:p.get('view')||'home',space:p.get('space'),channel:p.get('channel'),doc:p.get('doc')};if(!['home','space','inbox','graph','pinned','all','doc','board'].includes(route.view))route.view='home';if(route.view==='space'&&!spaceById(route.space))route={view:'home'};if(route.view==='doc'&&!docById(route.doc))route={view:'home'};filter='';navOpen=false;render();document.querySelector('.content-scroll')?.scrollTo(0,0);}
function navButton(view,label,ico,count){return `<button class="nav-row ${route.view===view?'active':''}" data-action="navigate" data-view="${view}">${icon(ico)}<span>${label}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`;}
function currentSpace(){return route.view==='doc'?spaceById(docById(route.doc)?.space):spaceById(route.space);}
function renderRail(){const cs=currentSpace();return `<nav class="rail" aria-label="Topic spaces"><button class="brand" data-action="navigate" data-view="home" title="Mind home" aria-label="Mind home"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M5 24V8l11 9L27 8v16M11 13v11m10-11v11" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/></svg></button><div class="rail-divider"></div><button class="space-button ${!cs?'active':''}" data-action="navigate" data-view="home" title="Your home" aria-label="Your home">${icon('home')}</button>${state.spaces.map(s=>`<button class="space-button ${cs?.id===s.id?'active':''}" data-action="space" data-id="${s.id}" title="${esc(s.name)}" aria-label="${esc(s.name)}">${icon(s.icon)}</button>`).join('')}<button class="space-button add" data-action="add-space" title="Create a space" aria-label="Create a space">${icon('plus')}</button><div class="rail-spacer"></div><button class="icon-button" data-action="guide" title="Workspace guide" aria-label="Workspace guide">${icon('help')}</button><button class="icon-button" data-action="settings" title="Workspace settings" aria-label="Workspace settings">${icon('settings')}</button><button class="avatar" data-action="settings" title="Personal workspace" aria-label="Personal workspace settings">KB</button></nav>`;}
function renderSidebar(){const cs=currentSpace();const channels=cs?.channels||['all-documents','reading-room'];const channelRoute=route.view==='doc'?docById(route.doc)?.channel:route.channel;const bytes=new Blob([JSON.stringify(state)]).size;return `<aside class="sidebar"><button class="workspace-button" data-action="settings"><div>Mind castle<span>Personal workspace</span></div>${icon('chevron')}</button><button class="search-button" data-action="search">${icon('search')}<span>Find anything</span><kbd>Ctrl K</kbd></button><div class="side-scroll">${navButton('home','Home','home')}${navButton('inbox','Inbox','inbox',state.documents.filter(d=>d.space==='inbox').length)}${navButton('graph','Knowledge graph','graph')}${navButton('pinned','Pinned','bookmark',state.documents.filter(d=>d.pinned).length)}<div class="section-label"><button data-action="collapse">${icon(collapsed?'right':'chevron')}${cs?esc(cs.name):'Your spaces'}</button><button class="add-small" data-action="${cs?'add-channel':'add-space'}" aria-label="${cs?'Add channel':'Add space'}">${icon('plus')}</button></div>${collapsed?'':cs?channels.map(c=>`<button class="nav-row channel-row ${channelRoute===c?'active':''}" data-action="channel" data-space="${cs.id}" data-channel="${esc(c)}"><span class="hash">#</span><span>${esc(c)}</span>${state.documents.some(d=>d.space===cs.id&&d.channel===c)?'<span class="channel-dot"></span>':''}</button>`).join(''):state.spaces.map(s=>`<button class="nav-row channel-row" data-action="space" data-id="${s.id}">${icon(s.icon)}<span>${esc(s.name)}</span>${icon('right')}</button>`).join('')}<div class="section-label">${icon('chevron')} Workspace</div><button class="nav-row channel-row ${route.view==='all'?'active':''}" data-action="navigate" data-view="all"><span class="hash">#</span><span>all-documents</span></button><button class="nav-row channel-row ${route.view==='board'?'active':''}" data-action="navigate" data-view="board"><span class="hash">#</span><span>research-board</span></button><button class="nav-row channel-row" data-action="guide"><span class="hash">#</span><span>getting-started</span></button><div class="section-label">${icon('chevron')} Pinned documents</div>${state.documents.filter(d=>d.pinned).slice(0,5).map(d=>`<button class="nav-row channel-row" data-action="open-doc" data-id="${d.id}">${icon(documentIcon(d))}<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(d.title)}</span></button>`).join('')}</div><button class="sidebar-bottom" data-action="settings" title="Storage and backups"><span class="storage-title">${icon('shield')} Your thoughts, your space</span><p>Saved on this device · ${(bytes/1024).toFixed(0)} KB</p><div class="storage-track"><span style="width:${Math.min(100,bytes/4000000*100)}%"></span></div><p>Export a backup to keep them safe.</p></button></aside>`;}
function renderTopbar(){const names={home:'Home',inbox:'Inbox',graph:'Knowledge graph',pinned:'Pinned',all:'All documents',board:'Research board',space:spaceName(route.space),doc:docById(route.doc)?.title};return `<header class="topbar"><button class="icon-button mobile-menu" data-action="mobile-nav" aria-label="Open navigation">${icon('menu')}</button>${icon(route.view==='graph'?'graph':'home')}<div class="breadcrumb"><span>Workspace</span><span class="slash">/</span><strong>${esc(names[route.view])}</strong></div><div class="top-actions"><span class="local-status">Local workspace</span><span class="topbar-divider"></span><button class="icon-button" data-action="search" aria-label="Search workspace" title="Search (Ctrl K)">${icon('search')}</button><button class="icon-button" data-action="toggle-inspector" aria-label="Toggle workspace details" title="Workspace details">${icon('panel')}</button></div></header>`;}
function castleArt(){return `<svg class="castle-art" viewBox="0 0 270 160" fill="none" aria-hidden="true"><defs><linearGradient id="castle-fill" x1="50" y1="10" x2="220" y2="160" gradientUnits="userSpaceOnUse"><stop stop-color="#b5bac1" stop-opacity=".25"/><stop offset="1" stop-color="#b5bac1" stop-opacity=".02"/></linearGradient></defs><ellipse cx="143" cy="135" rx="89" ry="20" stroke="#80848e" stroke-opacity=".25"/><ellipse cx="143" cy="135" rx="112" ry="29" stroke="#80848e" stroke-opacity=".15"/><path d="m77 117 65 27 64-31-65-23z" fill="#313338" stroke="#80848e"/><path d="M88 112V67l22-11 22 11v65l-22-10z M132 132V66l23-12 22 12v54 M177 121V78l20-10 19 10v35l-19 10-20-7" fill="url(#castle-fill)" stroke="#b5bac1" stroke-opacity=".7"/><path d="m88 67 22 10 22-10 M110 77v45 M132 66l23 10 22-10 M155 76v52 M177 78l20 9 19-9 M197 87v36" stroke="#b5bac1" stroke-opacity=".5"/><path d="M88 67V53l7-3v7l7-3v-7l8-4 8 4v7l7 3v-7l7 3v14 M132 66V43l8-4v9l7-3v-9l8-4 8 4v9l7 3v-9l7 4v23 M177 78V65l6-3v7l7-3v-7l7-3 7 3v7l6 3v-7l6 3v13" fill="#313338" stroke="#b5bac1" stroke-opacity=".7"/><path d="M119 115v-13q6-10 11-5v23 M145 97V84l5-2v13 M203 103V92l5-2v11 M96 88v-8l5 2v8" stroke="#dbdee1" stroke-opacity=".55"/><path d="M155 31V12l17 7-17 5" stroke="#b5bac1"/><circle cx="61" cy="66" r="2" fill="#dbdee1"/><circle cx="222" cy="48" r="1.5" fill="#dbdee1"/><path d="M208 20v8m-4-4h8 M71 94v6m-3-3h6" stroke="#dbdee1" stroke-opacity=".6"/></svg>`;}
function graphSVG(mini=false,docs=state.documents){const edges=graphEdges(docs),w=mini?210:850,h=mini?170:430;const nodes=docs.slice(0,80);const positions=new Map(nodes.map((d,i)=>{const angle=(i/Math.max(nodes.length,1))*Math.PI*2-.5;const rings=nodes.length>18?Math.floor(i/18)+1:1;const r=nodes.length>18?Math.min(.42,.14*rings):.31;return [d.id,{x:w/2+Math.cos(angle)*w*r,y:h/2+Math.sin(angle)*h*r}];}));return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Document connections">${edges.map(([a,b])=>{const p=positions.get(a),q=positions.get(b);return p&&q?`<line x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}" stroke="#80848e" stroke-width="${mini?1:1.3}" opacity=".5"/>`:'';}).join('')}${nodes.map((d,i)=>{const p=positions.get(d.id);return `<g class="network-node" data-action="open-doc" data-id="${d.id}" tabindex="0" role="button" aria-label="Open ${esc(d.title)}"><circle cx="${p.x}" cy="${p.y}" r="${mini?5:9}" fill="${spaceColor(d.space)}" stroke="${spaceColor(d.space)}" stroke-opacity=".2" stroke-width="${mini?7:13}"/><title>${esc(d.title)}</title>${mini?'':`<text x="${p.x}" y="${p.y+25}" text-anchor="middle">${esc(d.title.length>30?d.title.slice(0,28)+'…':d.title)}</text>`}</g>`;}).join('')}</svg>`;}
function renderInspector(){const doc=docById(route.doc);const backlinks=doc?state.documents.filter(d=>linksFrom(d).some(l=>l.id===doc.id)):[];return `<aside class="inspector ${inspectorOpen?'open':'user-hidden'}" aria-label="Workspace details"><div class="inspector-title">${icon('graph')} A connected mind <button class="icon-button" style="margin-left:auto" data-action="navigate" data-view="graph" aria-label="Open knowledge graph">${icon('arrow')}</button></div><div class="mini-graph">${graphSVG(true)}</div><div class="graph-caption"><span>${state.documents.length} documents</span><span>${graphEdges().length} connections</span></div><p>Good ideas rarely live alone.<br>Make a connection. See what grows.</p><div class="inspector-section"><h3 class="inspector-label">${doc?'Linked to this document':'Quick access'}</h3>${doc?(backlinks.length?backlinks.map(d=>`<button class="quick-link" data-action="open-doc" data-id="${d.id}">${icon('link')}<span>${esc(d.title)}</span>${icon('right')}</button>`).join(''):'<p>No backlinks yet. Link this title from another document to build a connection.</p>'):`<button class="quick-link" data-action="guide">${icon('book')}<span>Welcome to your mind castle</span>${icon('right')}</button><button class="quick-link" data-action="new-doc">${icon('plus')}<span>Capture a thought</span>${icon('right')}</button><button class="quick-link" data-action="export">${icon('download')}<span>Export your workspace</span>${icon('right')}</button>`}</div><div class="inspector-section"><h3 class="inspector-label">Around your workspace</h3>${state.activity.slice(0,3).map(a=>`<div class="activity-item"><strong>${esc(a.text)}</strong><span>${esc(a.detail)}</span></div>`).join('')||'<p>Your next idea starts here.</p>'}</div><div class="inspector-quote"><div class="quote-mark">“</div><blockquote>A place for unfinished thoughts<br>and unexpected connections.</blockquote><small>Your mind is a work in progress</small></div></aside>`;}
function cardsSpaces(){return `<div class="spaces-grid">${state.spaces.map(s=>{const count=state.documents.filter(d=>d.space===s.id).length;return `<button class="space-card" style="--accent:${s.color}" data-action="space" data-id="${s.id}"><div class="space-card-top"><span class="space-icon">${icon(s.icon)}</span>${icon('arrow')}</div><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="space-card-bottom"><span class="tiny-dot"></span>${count} document${count===1?'':'s'}<span>·</span>${s.channels.length} channels${icon('right')}</div></button>`;}).join('')}</div>`;}
function getDocs(){let docs=[...state.documents];if(route.view==='space')docs=docs.filter(d=>d.space===route.space&&(!route.channel||d.channel===route.channel));if(route.view==='inbox')docs=docs.filter(d=>d.space==='inbox');if(route.view==='pinned'||route.view==='home'&&tab==='pinned')docs=docs.filter(d=>d.pinned);if(filter){const q=filter.toLowerCase();docs=docs.filter(d=>[d.title,d.body,...d.tags].join(' ').toLowerCase().includes(q));}docs.sort(sort==='title'?(a,b)=>a.title.localeCompare(b.title):(a,b)=>new Date(b.updated)-new Date(a.updated));return docs;}
function docCard(d){return `<button class="doc-card" data-action="open-doc" data-id="${d.id}"><span class="document-type-icon">${icon(documentIcon(d))}</span><h3>${esc(d.title)}</h3><p>${esc(preview(d))}…</p><div class="doc-card-foot"><span class="tag" style="--accent:${spaceColor(d.space)}">${esc(spaceName(d.space))}</span><span class="status-pill ${d.status}">${statusLabel(d.status)}</span></div></button>`;}
function documentList(docs){if(!docs.length)return `<div class="empty-state">${icon(filter?'search':'file')}<h2>${filter?'No matching documents':'Room for your next idea'}</h2><p>${filter?'Try a different title, tag, or phrase.':'Capture a question, add a source, or start connecting your thoughts.'}</p>${filter?'':'<button class="primary-button" data-action="new-doc">Create a document</button>'}</div>`;if(layout==='grid')return `<div class="doc-grid">${docs.map(docCard).join('')}</div>`;return `<table class="document-table"><thead><tr><th>Document</th><th class="space-cell">Space</th><th class="optional">Stage</th><th class="date-cell">Updated</th><th><span class="sr-only" aria-label="Pin"></span></th></tr></thead><tbody>${docs.map(d=>`<tr><td><button class="document-name" data-action="open-doc" data-id="${d.id}"><span class="document-type-icon">${icon(documentIcon(d))}</span><span>${esc(d.title)}<span class="document-title-meta">${d.starter?'Starter · ':''}# ${esc(d.channel)}${d.tags.length?' · '+esc(d.tags[0]):''}</span></span></button></td><td class="space-cell"><span class="tag" style="--accent:${spaceColor(d.space)}">${esc(spaceName(d.space))}</span></td><td class="optional"><span class="status-pill ${d.status}">${statusLabel(d.status)}</span></td><td class="date-cell">${dateLabel(d.updated)}</td><td><button class="pin-button ${d.pinned?'pinned':''}" data-action="pin" data-id="${d.id}" aria-label="${d.pinned?'Unpin':'Pin'} ${esc(d.title)}" title="${d.pinned?'Unpin':'Pin'}">${icon('pin')}</button></td></tr>`).join('')}</tbody></table>`;}
function footer(){return `<div class="footer-tip">${icon('spark')} A thought worth keeping? <kbd>Ctrl K</kbd> to find it again.<span class="footer-right"><i></i> A little more connected.</span></div>`;}
function viewToggle(){return `<div class="view-toggle"><button data-action="layout" data-layout="list" class="${layout==='list'?'active':''}" aria-label="List view">${icon('list')}</button><button data-action="layout" data-layout="grid" class="${layout==='grid'?'active':''}" aria-label="Card view">${icon('grid')}</button></div>`;}
function renderHome(){const docs=getDocs();return `<div class="eyebrow">${icon('spark')} A little space for a bigger mind</div><div class="page-heading"><h1>Make yourself at home.</h1><button class="primary-button" data-action="new-doc">${icon('plus')} New document</button></div><p class="subtitle">Your ideas, research, and rabbit holes. All finding their place.</p><section class="hero"><div class="hero-copy"><div class="hero-label">${icon('book')} Welcome to your mind castle</div><h2>Collect freely. Connect deeply.</h2><p>A home for everything you’re curious about.<br>Start with a thought. Build a world of understanding.</p><button class="hero-link" data-action="guide">A quick tour of your workspace ${icon('arrow')}</button></div>${castleArt()}</section><div class="section-heading"><h2>Your spaces <span>${state.spaces.length}</span></h2><button class="text-button" data-action="add-space">${icon('plus')} Add a space</button></div>${cardsSpaces()}<div class="workspace-tabs"><button data-action="tab" data-tab="recent" class="${tab==='recent'?'active':''}">${icon('clock')} Recent documents</button><button data-action="tab" data-tab="pinned" class="${tab==='pinned'?'active':''}">${icon('pin')} Pinned <span class="tab-count">${state.documents.filter(d=>d.pinned).length}</span></button>${viewToggle()}</div>${documentList(docs.slice(0,8))}${docs.length>8?'<button class="text-button" data-action="navigate" data-view="all">View all documents →</button>':''}${footer()}`;}
function renderCollection(){const cs=spaceById(route.space);let title=route.view==='space'?(route.channel?'# '+route.channel:cs.name):({inbox:'A landing place for your thoughts.',pinned:'Keep the good things close.',all:'Everything, in one place.'})[route.view];const sub=route.view==='space'?(route.channel?`A channel in ${cs.name}. Collect, investigate, and connect.`:cs.description):({inbox:'Capture now. Find the right home for it later.',pinned:'The documents you want to return to.',all:'Every question, source, and connection across your workspace.'})[route.view];return `<div class="eyebrow">${icon(cs?.icon||'file')} ${cs?'Research space':'Your workspace'}</div><div class="page-heading"><h1>${esc(title)}</h1><button class="primary-button" data-action="new-doc">${icon('plus')} New document</button></div><p class="subtitle">${esc(sub)}</p>${cs?`<div class="page-toolbar"><button class="secondary-button" data-action="space" data-id="${cs.id}">All channels</button>${cs.channels.map(c=>`<button class="secondary-button" data-action="channel" data-space="${cs.id}" data-channel="${esc(c)}" ${route.channel===c?'style="border-color:#b5bac1;color:#dbdee1"':''}># ${esc(c)}</button>`).join('')}<button class="icon-button" data-action="add-channel" aria-label="Add channel">${icon('plus')}</button></div>`:''}<div class="page-toolbar"><input id="collection-filter" type="search" placeholder="Filter by title, content, or tag…" aria-label="Filter documents" value="${esc(filter)}"><select id="document-sort" aria-label="Sort documents"><option value="updated" ${sort==='updated'?'selected':''}>Recently updated</option><option value="title" ${sort==='title'?'selected':''}>Title A–Z</option></select>${viewToggle()}</div><div id="document-results">${documentList(getDocs())}</div>${footer()}`;}

function inlineMarkdown(text){
  let source=esc(text),tokens=[];
  const token=html=>{const idx=tokens.push(html)-1;return `\u0000${idx}\u0000`;};
  source=source.replace(/`([^`]+)`/g,(_,code)=>token(`<code>${code}</code>`));
  source=source.replace(/\[\[([^\]]+)\]\]/g,(_,title)=>token(`<button class="wiki-link" data-action="wiki" data-title="${title.trim()}">${title.trim()}</button>`));
  source=source.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,label,url)=>token(`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`));
  source=source.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/~~([^~]+)~~/g,'<s>$1</s>');
  return source.replace(/\u0000(\d+)\u0000/g,(_,i)=>tokens[Number(i)]||'');
}
function renderChart(body){const rows=body.split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(r=>r.length===2&&r[0]&&r[1]!==''&&Number.isFinite(Number(r[1]))&&Number(r[1])>=0);if(!rows.length)return `<pre><code>${esc(body)}</code></pre>`;const max=Math.max(...rows.map(r=>Number(r[1])),1);return `<div class="chart-panel" role="img" aria-label="Bar chart: ${esc(rows.map(r=>r.join(': ')).join(', '))}"><h3>At a glance</h3><p>Values from this document</p>${rows.map(([label,value])=>`<div class="bar-row"><span>${esc(label)}</span><div class="bar-track"><span style="width:${Number(value)/max*100}%"></span></div><span>${esc(value)}</span></div>`).join('')}</div>`;}
function markdown(body){
  const lines=body.replace(/\r\n/g,'\n').split('\n');let out='',i=0;
  const isTableDivider=line=>/^\s*\|?[\s:|-]+\|[\s:|-]*$/.test(line||'')&&line.includes('-');
  const cells=line=>line.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(x=>x.trim());
  while(i<lines.length){const line=lines[i];
    if(!line.trim()){i++;continue;}
    if(line.startsWith('```')){const language=line.slice(3).trim();let content=[];i++;while(i<lines.length&&!lines[i].startsWith('```'))content.push(lines[i++]);i++;const raw=content.join('\n');if(language==='chart')out+=renderChart(raw);else if(language==='diagram'){out+=`<div class="flow-diagram" aria-label="Process diagram">${raw.split(/\s*->\s*|\n/).filter(Boolean).map((node,n)=>`${n?'<span class="flow-arrow" aria-hidden="true">→</span>':''}<span class="flow-node">${esc(node)}</span>`).join('')}</div>`;}else out+=`<pre><code>${esc(raw)}</code></pre>`;continue;}
    if(/^#{1,3} /.test(line)){const level=line.match(/^#+/)[0].length;out+=`<h${level}>${inlineMarkdown(line.slice(level+1))}</h${level}>`;i++;continue;}
    if(/^\s*---+\s*$/.test(line)){out+='<hr>';i++;continue;}
    if(line.includes('|')&&isTableDivider(lines[i+1])){const headers=cells(line);i+=2;const rows=[];while(i<lines.length&&lines[i].includes('|')&&lines[i].trim())rows.push(cells(lines[i++]));out+=`<div class="table-scroll"><table><thead><tr>${headers.map(c=>`<th>${inlineMarkdown(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${headers.map((_,idx)=>`<td>${inlineMarkdown(row[idx]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;continue;}
    if(/^> ?/.test(line)){const quote=[];while(i<lines.length&&/^> ?/.test(lines[i]))quote.push(lines[i++].replace(/^> ?/,''));out+=`<blockquote>${quote.map(inlineMarkdown).join('<br>')}</blockquote>`;continue;}
    if(/^\s*[-*] /.test(line)||/^\s*\d+\. /.test(line)){const ordered=/^\s*\d+\. /.test(line),tag=ordered?'ol':'ul';out+=`<${tag}>`;while(i<lines.length&&(ordered?/^\s*\d+\. /:/^\s*[-*] /).test(lines[i])){const item=lines[i++].replace(ordered?/^\s*\d+\. /:/^\s*[-*] /,'');const task=item.match(/^\[([ xX])\] (.*)$/);out+=task?`<li class="task-item"><span class="task-box" aria-label="${task[1]===' '?'Unchecked':'Checked'}">${task[1]===' '?'':'✓'}</span>${inlineMarkdown(task[2])}</li>`:`<li>${inlineMarkdown(item)}</li>`;}out+=`</${tag}>`;continue;}
    const paragraph=[line];i++;while(i<lines.length&&lines[i].trim()&&!/^(#{1,3} |>|```|[-*] |\d+\. |---)/.test(lines[i])&&!(lines[i].includes('|')&&isTableDivider(lines[i+1])))paragraph.push(lines[i++]);out+=`<p>${paragraph.map(inlineMarkdown).join('<br>')}</p>`;
  }return out;
}
function renderDocument(){const d=docById(route.doc);const links=linksFrom(d);return `<article class="document-reader"><div class="reader-topline"><button class="reader-back" data-action="doc-parent" data-id="${d.id}">${icon('back')} ${esc(spaceName(d.space))} / ${esc(d.channel)}</button><div class="reader-actions"><button class="icon-button ${d.pinned?'pinned':''}" data-action="pin" data-id="${d.id}" title="${d.pinned?'Unpin':'Pin'} document" aria-label="${d.pinned?'Unpin':'Pin'} document">${icon('pin')}</button><button class="secondary-button" data-action="export-doc" data-id="${d.id}" title="Download Markdown">${icon('download')} Export</button><button class="primary-button" data-action="edit-doc" data-id="${d.id}">${icon('edit')} Edit</button><button class="icon-button" data-action="delete-doc" data-id="${d.id}" title="Delete document" aria-label="Delete document">${icon('trash')}</button></div></div><div class="eyebrow">${icon(documentIcon(d))} ${esc(d.type)} · ${esc(spaceName(d.space))}</div><h1 style="margin-top:12px">${esc(d.title)}</h1><div class="reader-meta"><span class="status-pill ${d.status}">${statusLabel(d.status)}</span><span>Updated ${dateLabel(d.updated)}</span><span>${d.body.split(/\s+/).filter(Boolean).length} words</span><span>${links.length} linked document${links.length===1?'':'s'}</span></div>${d.tags.length?`<div class="doc-tags">${d.tags.map(t=>`<span># ${esc(t)}</span>`).join('')}</div>`:''}${d.starter?'<div class="reader-note">An editable starting point · This is a template, not completed research.</div>':''}<div class="rich-document">${markdown(d.body)}</div>${links.length?`<section class="document-links"><h3>Connected documents</h3>${links.map(l=>`<button data-action="open-doc" data-id="${l.id}">${icon('link')}${esc(l.title)}</button>`).join('')}</section>`:''}</article>`;}
function renderGraph(){return `<div class="eyebrow">${icon('graph')} Follow the connections</div><div class="page-heading"><h1>Nothing exists in isolation.</h1><button class="primary-button" data-action="new-doc">${icon('plus')} New document</button></div><p class="subtitle">Every line is a link between documents. Select a node to follow the thought.</p><div class="network-panel"><div class="network-summary">${state.documents.length} documents · ${graphEdges().length} connections${state.documents.length>80?' · showing the first 80 documents':''}</div>${graphSVG()}<div class="network-legend">${state.spaces.map(s=>`<span style="--accent:${s.color}"><i></i>${esc(s.name)}</span>`).join('')}<span style="--accent:#949cf7"><i></i>Inbox</span></div></div><p class="small-info">Create a connection by writing <code>[[An exact document title]]</code> inside another document. Linked notes will also appear as backlinks.</p>${footer()}`;}
function renderBoard(){return `<div class="eyebrow">${icon('board')} Ideas in motion</div><div class="page-heading"><h1>Let your thinking take shape.</h1><button class="primary-button" data-action="new-doc">${icon('plus')} New document</button></div><p class="subtitle">From a first question to a growing body of knowledge. Change a document’s stage in the editor.</p><div class="board">${['seed','draft','growing'].map(status=>{const docs=state.documents.filter(d=>d.status===status);return `<section class="board-column"><h3><span class="status-pill ${status}">${statusLabel(status)}</span><span>${docs.length}</span></h3>${docs.length?docs.map(docCard).join(''):'<div class="board-empty">Space for what comes next.</div>'}</section>`;}).join('')}</div>`;}
function render(){const scroll=document.querySelector('.content-scroll')?.scrollTop||0;app.innerHTML=`<div class="app-shell ${navOpen?'nav-open':''}"><button class="nav-scrim" data-action="mobile-nav" aria-label="Close navigation"></button>${renderRail()}${renderSidebar()}<main class="main">${renderTopbar()}${loadError?`<div class="save-warning">${esc(loadError)}</div>`:''}<div class="workspace-content"><div class="content-scroll"><div class="page-wrap">${route.view==='home'?renderHome():route.view==='doc'?renderDocument():route.view==='graph'?renderGraph():route.view==='board'?renderBoard():renderCollection()}</div></div>${renderInspector()}</div></main></div>`;document.querySelector('.content-scroll').scrollTop=scroll;document.title=`${route.view==='doc'?docById(route.doc).title:route.view==='space'?spaceName(route.space):'Your workspace'} — Mind`;}

function openModal(content,wide=false,extra=''){modalReturnFocus=document.activeElement;overlay.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''} ${extra}" role="dialog" aria-modal="true" aria-label="${extra==='search-modal'?'Search workspace':'Workspace dialog'}">${content}</section></div>`;setTimeout(()=>overlay.querySelector('input,textarea,button,select')?.focus(),30);}
function modalHeader(title){return `<div class="modal-header"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>`;}
function closeModal(force=false){if(editorDirty&&!force){if(!window.confirm('Discard your unsaved document changes?'))return;}editorDirty=false;overlay.innerHTML='';modalReturnFocus?.focus();}
function spaceOptions(selected){return `<option value="inbox" ${selected==='inbox'?'selected':''}>Inbox</option>${state.spaces.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}`;}
function channelOptions(sid,selected){const channels=sid==='inbox'?['inbox']:spaceById(sid)?.channels||['overview'];return channels.map(c=>`<option ${c===selected?'selected':''}>${esc(c)}</option>`).join('');}
function openEditor(did=null,title=''){const d=did?docById(did):null;const sid=d?.space||route.space||'inbox';const ch=d?.channel||route.channel;editorDirty=false;openModal(`${modalHeader(d?'Make room for the next version.':'A thought worth keeping.')}<form id="document-form" data-id="${d?.id||''}"><label for="doc-title">Document title</label><input id="doc-title" name="title" required maxlength="200" placeholder="Give your thought a name…" value="${esc(d?.title||title)}"><div class="form-row"><div><label for="doc-space">Space</label><select id="doc-space" name="space">${spaceOptions(sid)}</select></div><div><label for="doc-channel">Channel</label><select id="doc-channel" name="channel">${channelOptions(sid,ch)}</select></div><div><label for="doc-status">Stage</label><select id="doc-status" name="status">${['seed','draft','growing'].map(s=>`<option value="${s}" ${d?.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></div><div><label for="doc-type">Format</label><select id="doc-type" name="type">${['document','table','diagram'].map(t=>`<option value="${t}" ${d?.type===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div></div><div class="editor-toolbar"><button type="button" data-action="insert" data-kind="heading">H2</button><button type="button" data-action="insert" data-kind="bold"><b>Bold</b></button><button type="button" data-action="insert" data-kind="list">List</button><button type="button" data-action="insert" data-kind="checklist">Checklist</button><button type="button" data-action="insert" data-kind="table">Table</button><button type="button" data-action="insert" data-kind="diagram">Diagram</button><button type="button" data-action="insert" data-kind="chart">Chart</button><button type="button" data-action="insert" data-kind="link">[[Link]]</button><span class="toolbar-spacer"></span><button type="button" data-action="preview-editor">Preview</button></div><label for="doc-body" style="position:absolute;clip:rect(0,0,0,0)">Document content in Markdown</label><textarea class="editor-content" id="doc-body" name="body" maxlength="1000000" placeholder="Start with a question, a source, or an unfinished idea…">${esc(d?.body||'')}</textarea><div id="editor-preview" class="rich-document" style="display:none;min-height:240px;max-height:42vh;overflow:auto;padding:15px;border:1px solid #383a40;border-radius:6px"></div><div class="editor-hint">Markdown supported · Connect documents with [[Exact document title]] · Tables, checklists, and chart / diagram code blocks.</div><label for="doc-tags">Tags · comma separated</label><input id="doc-tags" name="tags" maxlength="1800" placeholder="research, open-question, source…" value="${esc(d?.tags.join(', ')||'')}"><p class="form-error" id="form-error" role="alert"></p><div class="modal-actions"><button class="secondary-button" type="button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit">${icon('check')} Save document</button></div></form>`,true);}
function openSpaceForm(){openModal(`${modalHeader('A new wing of your castle.')}<p>A space brings a broad topic together. Add channels as your research branches out.</p><form id="space-form"><label for="space-name">Space name</label><input id="space-name" name="name" required maxlength="100" placeholder="e.g. Technology & society"><label for="space-description">A short description</label><input id="space-description" name="description" maxlength="160" placeholder="What are you curious about?"><div class="form-row"><div><label for="space-icon">Icon</label><select id="space-icon" name="icon"><option value="book">Book</option><option value="globe">World</option><option value="philosophy">Mind</option><option value="briefcase">Work</option><option value="religion">Sun</option><option value="graph">Connections</option></select></div><div><label for="space-color">Color</label><select id="space-color" name="color"><option value="#eb459e">Fuchsia</option><option value="#57f287">Green</option><option value="#5865f2">Blurple</option><option value="#fee75c">Yellow</option><option value="#ed4245">Red</option></select></div></div><p class="form-error" id="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit">Create space</button></div></form>`);}
function openChannelForm(){const cs=currentSpace();if(!cs)return openSpaceForm();openModal(`${modalHeader('Follow a new thread.')}<p>Add a channel to ${esc(cs.name)}.</p><form id="channel-form" data-space="${cs.id}"><label for="channel-name">Channel name</label><input id="channel-name" name="name" required maxlength="100" placeholder="e.g. open-questions"><p class="form-error" id="form-error" role="alert"></p><div class="modal-actions"><button class="secondary-button" type="button" data-action="close-modal">Cancel</button><button class="primary-button" type="submit">Create channel</button></div></form>`);}
function openSearch(){openModal(`<div class="search-input-wrap">${icon('search')}<input id="global-search" aria-label="Search titles, content, and tags" placeholder="A title, a thought, a connection…" autocomplete="off"><button class="icon-button" data-action="close-modal" aria-label="Close search">${icon('close')}</button></div><div class="search-results" id="search-results"></div><div class="search-footer">Search titles, full document content, and tags · Esc to close</div>`,false,'search-modal');updateSearch('');}
function updateSearch(query){const q=query.trim().toLowerCase(),docs=state.documents.filter(d=>!q||[d.title,d.body,...d.tags].join(' ').toLowerCase().includes(q)).slice(0,30);document.getElementById('search-results').innerHTML=docs.length?docs.map(d=>`<button class="search-result" data-action="search-open" data-id="${d.id}"><span class="document-type-icon">${icon(documentIcon(d))}</span><div><strong>${esc(d.title)}</strong><small>${esc(spaceName(d.space))} · # ${esc(d.channel)}</small></div>${icon('right')}</button>`).join(''):`<div style="padding:25px;color:#b5bac1;font-size:12px">No matching thoughts yet. Try another phrase.</div>`;}
function openSettings(){openModal(`${modalHeader('Your workspace, your way.')}<p>Mind is a personal, browser-local research workspace. No account is required. Content is saved on this device; it does not sync between browsers.</p><div class="settings-row"><div><strong>Export a workspace backup</strong><p>All spaces, channels, documents, and connections in one portable JSON file.</p></div><button class="secondary-button" data-action="export">${icon('download')} Export</button></div><div class="settings-row"><div><strong>Import a workspace</strong><p>Restore a Mind backup. Review its contents before replacing this workspace.</p></div><button class="secondary-button" data-action="import">${icon('upload')} Import</button></div>${loadError?'<div class="settings-row"><div><strong>Recover unreadable saved data</strong><p>Download the original stored data before resetting.</p></div><button class="secondary-button" data-action="recover">Download raw data</button></div>':''}<div class="settings-row"><div><strong>Markdown documents</strong><p>Open any document and choose Export for a portable .md file. Internal links use [[Document title]].</p></div></div><div class="settings-row"><div><strong>Keyboard shortcuts</strong><p>Ctrl / ⌘ K — search · Esc — close dialog · Ctrl / ⌘ S — save in the editor</p></div></div><div class="settings-row"><div><strong>Start fresh</strong><p>Remove all locally saved documents and restore the starter workspace. Export a backup first.</p></div><button class="secondary-button danger" data-action="reset-confirm">Reset</button></div>`);}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportWorkspace(){download(`mind-workspace-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2),'application/json');notify('Workspace backup downloaded. Keep it somewhere safe.');}
function guide(){const d=docById('welcome');if(d)navigate('doc',{doc:d.id});else openModal(`${modalHeader('Find your way around.')}<div class="onboarding-grid"><div><strong>Spaces & channels</strong><p>Create broad spaces and specific channels. Give every idea a home.</p></div><div><strong>Documents</strong><p>Write Markdown, tables, charts, and diagrams. Edit anytime.</p></div><div><strong>Connections</strong><p>Write [[Document title]] to connect ideas. Explore the graph to follow them.</p></div><div><strong>Portable by design</strong><p>Export regular backups. Import them to move your workspace to another browser.</p></div></div>`);}

document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,did=el.dataset.id;
  switch(action){
    case'navigate':navigate(el.dataset.view);break;
    case'space':navigate('space',{space:did});break;
    case'channel':navigate('space',{space:el.dataset.space,channel:el.dataset.channel});break;
    case'open-doc':navigate('doc',{doc:did});break;
    case'search-open':closeModal(true);navigate('doc',{doc:did});break;
    case'doc-parent':{const d=docById(did);navigate(d.space==='inbox'?'inbox':'space',d.space==='inbox'?{}:{space:d.space,channel:d.channel});break;}
    case'new-doc':openEditor();break;
    case'edit-doc':openEditor(did);break;
    case'add-space':openSpaceForm();break;
    case'add-channel':openChannelForm();break;
    case'collapse':collapsed=!collapsed;render();break;
    case'tab':tab=el.dataset.tab;render();break;
    case'layout':layout=el.dataset.layout;render();break;
    case'pin':mutate(next=>{const d=next.documents.find(d=>d.id===did);d.pinned=!d.pinned;},docById(did).pinned?'Document unpinned.':'Pinned for easy access.');break;
    case'search':openSearch();break;
    case'settings':openSettings();break;
    case'guide':guide();break;
    case'toggle-inspector':inspectorOpen=!inspectorOpen;document.querySelector('.inspector').classList.toggle('open',inspectorOpen);document.querySelector('.inspector').classList.toggle('user-hidden',!inspectorOpen);break;
    case'mobile-nav':navOpen=!navOpen;if(navOpen){inspectorOpen=false;document.querySelector('.inspector').classList.remove('open');document.querySelector('.inspector').classList.add('user-hidden');}document.querySelector('.app-shell').classList.toggle('nav-open',navOpen);break;
    case'close-modal':closeModal();break;
    case'export':exportWorkspace();break;
    case'import':document.getElementById('import-file').click();break;
    case'recover':try{download('mind-recovery.json',localStorage.getItem(STORAGE_KEY)||'','application/json');}catch(e){notify('Browser storage is unavailable.');}break;
    case'export-doc':{const d=docById(did);download(`${d.title.replace(/[^\p{L}\p{N} -]/gu,'').slice(0,80)||'document'}.md`,`# ${d.title}\n\n${d.body}\n`,'text/markdown');notify('Markdown document downloaded.');break;}
    case'wiki':{if(el.closest('#editor-preview'))break;const title=el.dataset.title,d=state.documents.find(d=>d.title.toLowerCase()===title.toLowerCase());if(d)navigate('doc',{doc:d.id});else{openModal(`${modalHeader('An idea waiting for a home.')}<p>“${esc(title)}” does not have a document yet. Create it to complete the connection.</p><div class="modal-actions"><button class="secondary-button" data-action="close-modal">Not now</button><button class="primary-button" data-action="create-linked" data-title="${esc(title)}">Create document</button></div>`);}break;}
    case'create-linked':openEditor(null,el.dataset.title);break;
    case'insert':{const textarea=document.getElementById('doc-body'),selection=textarea.value.slice(textarea.selectionStart,textarea.selectionEnd);const snippets={heading:'\n## '+(selection||'Heading')+'\n',bold:'**'+(selection||'Important thought')+'**',list:'\n- First thought\n- Second thought\n',checklist:'\n- [ ] A next step\n- [ ] Another step\n',table:'\n| Topic | Evidence | Notes |\n| --- | --- | --- |\n| Example | Source | Interpretation |\n',diagram:'\n```diagram\nQuestion -> Evidence -> Understanding\n```\n',chart:'\n```chart\nCategory A | 8\nCategory B | 5\nCategory C | 3\n```\n',link:'[['+(selection||'Document title')+']]'};textarea.setRangeText(snippets[el.dataset.kind],textarea.selectionStart,textarea.selectionEnd,'end');textarea.focus();editorDirty=true;document.getElementById('editor-preview').style.display='none';textarea.style.display='';break;}
    case'preview-editor':{const preview=document.getElementById('editor-preview'),textarea=document.getElementById('doc-body'),show=preview.style.display==='none';preview.innerHTML=markdown(textarea.value);preview.style.display=show?'block':'none';textarea.style.display=show?'none':'';el.textContent=show?'Write':'Preview';break;}
    case'delete-doc':{const d=docById(did);openModal(`${modalHeader('Delete this document?')}<p>“${esc(d.title)}” will be removed from this browser. Links to it will remain unresolved. Export it first if you want a copy.</p><div class="modal-actions"><button class="secondary-button" data-action="close-modal">Keep it</button><button class="secondary-button danger" data-action="confirm-delete" data-id="${did}">Delete document</button></div>`);break;}
    case'confirm-delete':{const d=docById(did);if(mutate(next=>{next.documents=next.documents.filter(x=>x.id!==did);activity(next,'A document removed',d.title);},'Document deleted.')){closeModal(true);navigate('home');}break;}
    case'reset-confirm':openModal(`${modalHeader('Reset this workspace?')}<p>This removes all local changes and brings back the starter documents. Download a backup before continuing.</p><div class="modal-actions"><button class="secondary-button" data-action="export">Export backup</button><button class="secondary-button" data-action="close-modal">Cancel</button><button class="secondary-button danger" data-action="reset">Reset workspace</button></div>`);break;
    case'reset':{const oldError=loadError;loadError='';if(saveState(initialState())){closeModal(true);navigate('home');notify('Starter workspace restored.');}else loadError=oldError;break;}
  }
});
document.addEventListener('submit',event=>{if(!['document-form','space-form','channel-form'].includes(event.target.id))return;event.preventDefault();const form=event.target,f=new FormData(form),error=document.getElementById('form-error');
  if(form.id==='document-form'){
    const title=f.get('title').trim();if(!title){error.textContent='Give this document a title.';return;}
    if(state.documents.some(d=>d.id!==form.dataset.id&&d.title.toLowerCase()===title.toLowerCase())){error.textContent='A document with this title already exists. Use a unique title so links find the right document.';return;}
    const tags=[...new Set(f.get('tags').split(',').map(t=>t.trim()).filter(Boolean))];if(tags.length>30||tags.some(t=>t.length>60)){error.textContent='Use up to 30 tags, each 60 characters or fewer.';return;}
    const old=docById(form.dataset.id),did=old?.id||id('doc');const item={id:did,title,space:f.get('space'),channel:f.get('channel'),status:f.get('status'),type:f.get('type'),body:f.get('body'),tags,pinned:old?.pinned||false,starter:false,created:old?.created||now(),updated:now()};
    if(!saveState((()=>{const next=structuredClone(state);if(old)next.documents[next.documents.findIndex(d=>d.id===did)]=item;else next.documents.unshift(item);if(old&&old.title!==title){for(const linked of next.documents){const before=linked.body;linked.body=linked.body.replace(/\[\[([^\]\n]+)\]\]/g,(match,target)=>target.trim().toLowerCase()===old.title.toLowerCase()?`[[${title}]]`:match);if(linked.body!==before)linked.updated=now();}}activity(next,old?'A thought developed':'A new thought captured',title);return next;})()))return;
    editorDirty=false;closeModal(true);navigate('doc',{doc:did});notify('Document saved on this device.');
  }else if(form.id==='space-form'){
    const name=f.get('name').trim();if(!name){error.textContent='Give this space a name.';return;}if(state.spaces.some(s=>s.name.toLowerCase()===name.toLowerCase())){error.textContent='A space with this name already exists.';return;}const sid=id('space');if(mutate(next=>{next.spaces.push({id:sid,name,description:f.get('description').trim(),icon:f.get('icon'),color:f.get('color'),channels:['overview','sources']});activity(next,'A new space opened',name);},'Your new space is ready.')){closeModal(true);navigate('space',{space:sid});}
  }else{
    const name=f.get('name').trim().toLowerCase().replace(/\s+/g,'-'),sid=form.dataset.space;if(!name){error.textContent='Give this channel a name.';return;}if(spaceById(sid).channels.includes(name)){error.textContent='This channel already exists.';return;}if(mutate(next=>{next.spaces.find(s=>s.id===sid).channels.push(name);},'Channel created.')){closeModal(true);navigate('space',{space:sid,channel:name});}
  }
});
document.addEventListener('input',event=>{if(event.target.id==='global-search')updateSearch(event.target.value);if(event.target.closest('#document-form'))editorDirty=true;if(event.target.id==='collection-filter'){filter=event.target.value;document.getElementById('document-results').innerHTML=documentList(getDocs());}});
document.addEventListener('change',event=>{if(event.target.id==='doc-space'){document.getElementById('doc-channel').innerHTML=channelOptions(event.target.value);editorDirty=true;}if(event.target.id==='document-sort'){sort=event.target.value;document.getElementById('document-results').innerHTML=documentList(getDocs());}});
document.addEventListener('keydown',event=>{
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(editorDirty)return;openSearch();}
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'&&document.getElementById('document-form')){event.preventDefault();document.getElementById('document-form').requestSubmit();}
  if(event.key==='Escape'){if(overlay.innerHTML)closeModal();else if(navOpen){navOpen=false;render();}else if(inspectorOpen){inspectorOpen=false;render();}}
  if(event.target.matches('g[data-action]')&&(event.key==='Enter'||event.key===' ')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}
  if(event.key==='Tab'&&overlay.innerHTML){const focusable=[...overlay.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  if(event.key==='Enter'&&event.target.id==='global-search'){event.preventDefault();document.querySelector('.search-result')?.click();}
});
window.addEventListener('beforeunload',event=>{if(editorDirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',readRoute);
window.matchMedia('(max-width:1250px)').addEventListener('change',event=>{inspectorOpen=!event.matches;render();});
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY){if(editorDirty){notify('Another tab changed this workspace. Export your draft before refreshing.');return;}try{if(event.newValue){state=validateState(JSON.parse(event.newValue));storedSnapshot=event.newValue;readRoute();notify('Workspace updated from another tab.');}}catch(e){notify('Another tab saved unreadable data. Export a backup before reloading.');}}});
document.getElementById('import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>20*1024*1024){notify('This backup is too large. Choose a file smaller than 20 MB.');return;}try{const imported=validateState(JSON.parse(await file.text()));openModal(`${modalHeader('Restore this workspace?')}<p>This backup contains <strong>${imported.spaces.length} spaces</strong> and <strong>${imported.documents.length} documents</strong>. Importing will replace the workspace currently stored in this browser.</p><p>Export the current workspace first if you want to keep both.</p><div class="modal-actions"><button class="secondary-button" data-action="export">Export current</button><button class="secondary-button" data-action="close-modal">Cancel</button><button class="primary-button" id="confirm-import">Replace & restore</button></div>`);document.getElementById('confirm-import').addEventListener('click',()=>{if(saveState(imported)){closeModal(true);navigate('home');notify('Workspace restored from backup.');}});}catch(e){notify(e.message.startsWith('A ')||e.message.startsWith('This ')?e.message:'This file is not a valid Mind workspace backup.');}});
// Expose pure helpers for the dependency-free regression suite.
window.MindCore={validateState,initialState,markdown,inlineMarkdown,graphEdges,linksFrom};
if(storedSnapshot===null&&!loadError)saveState(state);
readRoute();
